#include <Wire.h>

void setup() {
  Wire.begin();
  Serial.begin(9600);
}

// Scan for I2C devices
void loop() {
  for (byte addr = 1; addr < 127; addr++) {
    Wire.beginTransmission(addr);
    if (Wire.endTransmission() == 0) {
      Serial.print("Found device at 0x");
      Serial.println(addr, HEX);
    }
  }
  delay(5000);
}

#include <SPI.h>

void setup() {
  SPI.begin();
  pinMode(SS, OUTPUT);
}

void sendByte(byte data) {
  digitalWrite(SS, LOW);
  SPI.transfer(data);
  digitalWrite(SS, HIGH);
}
